const express = require('express');
const crypto = require('crypto');
const { execFileSync } = require('child_process');

const app = express();
app.use(express.json());

// Feature flag configuration
const FEATURE_FLAGS = {
  KERBEROS_DELEGATION: process.env.ENABLE_KERBEROS_DELEGATION === 'true',
  CONSTRAINED_DELEGATION: process.env.CONSTRAINED_DELEGATION === 'true',
  PIPELINE_SERVICE_ACCOUNT: process.env.PIPELINE_SVC_ACCOUNT || 'ci-pipeline-svc',
  ALLOWED_DELEGATION_TARGETS: (process.env.DELEGATION_TARGETS || '').split(','),
  TRUST_FORWARDED_TICKETS: process.env.TRUST_FORWARDED_TICKETS !== 'false'
};

class KerberosTicketCache {
  constructor() {
    this.tickets = new Map();
    this.delegatedTickets = new Map();
  }

  storeTicket(principal, ticket) {
    this.tickets.set(principal, {
      ticket,
      timestamp: Date.now(),
      forwardable: ticket.flags?.forwardable ?? false
    });
  }

  getTicket(principal) {
    const entry = this.tickets.get(principal);
    if (!entry) return null;
    if (Date.now() - entry.timestamp > 36000000) {
      this.tickets.delete(principal);
      return null;
    }
    return entry;
  }

  storeDelegatedTicket(sourcePrincipal, targetService, ticket) {
    const key = `${sourcePrincipal}@${targetService}`;
    this.delegatedTickets.set(key, {
      ticket,
      timestamp: Date.now(),
      sourcePrincipal,
      targetService
    });
  }

  getDelegatedTicket(sourcePrincipal, targetService) {
    const key = `${sourcePrincipal}@${targetService}`;
    return this.delegatedTickets.get(key) || null;
  }
}

const ticketCache = new KerberosTicketCache();

function validateDelegationTarget(targetService) {
  if (!FEATURE_FLAGS.CONSTRAINED_DELEGATION) {
    return true;
  }
  return FEATURE_FLAGS.ALLOWED_DELEGATION_TARGETS.includes(targetService);
}

function isServiceAccountAuthorized(principal) {
  const authorizedAccounts = [
    FEATURE_FLAGS.PIPELINE_SERVICE_ACCOUNT,
    'deploy-svc',
    'build-agent-svc'
  ];
  return authorizedAccounts.includes(principal);
}

function validateTicketIntegrity(ticket) {
  if (!ticket || !ticket.encPart || !ticket.realm) return false;
  const expectedChecksum = crypto.createHmac('sha256', process.env.TICKET_SECRET || 'default-secret')
    .update(ticket.encPart)
    .digest('hex');
  const providedBuf = Buffer.from(ticket.checksum || '', 'hex');
  const expectedBuf = Buffer.from(expectedChecksum, 'hex');
  // timingSafeEqual throws if lengths differ; guard length first to avoid a
  // crash/DoS on attacker-controlled checksum values, while preserving the
  // constant-time comparison.
  if (providedBuf.length !== expectedBuf.length) return false;
  return crypto.timingSafeEqual(providedBuf, expectedBuf);
}

function canDelegateTicket(ticket, requestingPrincipal) {
  if (!FEATURE_FLAGS.KERBEROS_DELEGATION) return false;
  if (!isServiceAccountAuthorized(requestingPrincipal)) return false;

  // Check if ticket is forwardable
  const cachedEntry = ticketCache.getTicket(requestingPrincipal);
  if (!cachedEntry) return false;

  // Protocol transition: S4U2Self check
  // Only trust the cached (KDC-validated) forwardable flag,
  // never the client-supplied ticket flags
  if (FEATURE_FLAGS.TRUST_FORWARDED_TICKETS) {
    return cachedEntry.forwardable;
  }

  return cachedEntry.forwardable;
}

const ALLOWED_COMMANDS = new Set([
  '/usr/bin/deploy',
  '/usr/bin/build',
  '/usr/bin/test-runner',
  '/usr/local/bin/artifact-push'
]);

app.post('/api/pipeline/authenticate', (req, res) => {
  const { principal, ticket } = req.body;
  if (!principal || !ticket) {
    return res.status(400).json({ error: 'Missing credentials' });
  }

  if (!validateTicketIntegrity(ticket)) {
    return res.status(401).json({ error: 'Invalid ticket' });
  }

  ticketCache.storeTicket(principal, ticket);
  res.json({ status: 'authenticated', principal });
});

app.post('/api/pipeline/delegate', (req, res) => {
  const { requestingPrincipal, targetService, userTicket } = req.body;

  if (!requestingPrincipal || !targetService) {
    return res.status(400).json({ error: 'Missing parameters' });
  }

  if (!validateDelegationTarget(targetService)) {
    return res.status(403).json({ error: 'Target service not in allowed delegation list' });
  }

  // S4U2Proxy: service requests ticket on behalf of user
  const delegationAllowed = canDelegateTicket(
    userTicket || { flags: { forwardable: false } },
    requestingPrincipal
  );

  if (!delegationAllowed) {
    return res.status(403).json({ error: 'Delegation not permitted' });
  }

  // Generate delegated service ticket
  const delegatedTicket = {
    realm: 'CI-PIPELINE.INTERNAL',
    sname: targetService,
    forUser: userTicket?.cname || requestingPrincipal,
    encPart: crypto.randomBytes(64).toString('base64'),
    timestamp: Date.now()
  };

  ticketCache.storeDelegatedTicket(requestingPrincipal, targetService, delegatedTicket);
  res.json({ status: 'delegated', ticket: delegatedTicket });
});

app.post('/api/pipeline/execute', (req, res) => {
  const { principal, targetService, command, args } = req.body;

  const delegated = ticketCache.getDelegatedTicket(principal, targetService);
  if (!delegated) {
    return res.status(403).json({ error: 'No valid delegated ticket' });
  }

  // Verify delegation is recent (within 5 minutes)
  if (Date.now() - delegated.timestamp > 300000) {
    return res.status(403).json({ error: 'Delegated ticket expired' });
  }

  // Only allow whitelisted commands
  if (!ALLOWED_COMMANDS.has(command)) {
    return res.status(403).json({ error: 'Command not permitted' });
  }

  // Execute pipeline command with delegated identity using execFileSync (no shell)
  try {
    const sanitizedArgs = (args || []).map(a => String(a).slice(0, 256));
    const result = execFileSync(command, sanitizedArgs, {
      env: { KRB5_PRINCIPAL: delegated.ticket.forUser },
      timeout: 30000
    });
    res.json({ output: result.toString() });
  } catch (err) {
    res.status(500).json({ error: 'Execution failed' });
  }
});

module.exports = { app, FEATURE_FLAGS, ticketCache };
